(660,'mwai_options','a:107:{s:6:\"addons\";a:11:{i:0;a:7:{s:4:\"slug\";s:18:\"mwai-notifications\";s:4:\"name\";s:13:\"Notifications\";s:11:\"description\";s:95:\"Get real-time alerts for new discussions in your chatbot, so you never miss a chance to engage.\";s:11:\"install_url\";s:49:\"https://meowapps.com/products/mwai-notifications/\";s:12:\"settings_url\";N;s:5:\"stars\";i:4;s:7:\"enabled\";b:0;}i:1;a:7:{s:4:\"slug\";s:11:\"mwai-ollama\";s:4:\"name\";s:6:\"Ollama\";s:11:\"description\";s:114:\"Leverage local LLM integration through Ollama; refresh and use your own models for a flexible, cost-free approach.\";s:11:\"install_url\";s:42:\"https://meowapps.com/products/mwai-ollama/\";s:12:\"settings_url\";N;s:5:\"stars\";i:3;s:7:\"enabled\";b:0;}i:2;a:7:{s:4:\"slug\";s:13:\"mwai-deepseek\";s:4:\"name\";s:8:\"DeepSeek\";s:11:\"description\";s:87:\"Support for DeepSeek, a Chinese AI company that provides extremely powerful LLM models.\";s:11:\"install_url\";s:39:\"https://meowapps.com/products/deepseek/\";s:12:\"settings_url\";N;s:5:\"stars\";i:3;s:7:\"enabled\";b:0;}i:3;a:7:{s:4:\"slug\";s:14:\"mwai-websearch\";s:4:\"name\";s:10:\"Web Search\";s:11:\"description\";s:102:\"Enhance chatbot responses by pulling context from Google and Tavily, delivering more accurate answers.\";s:11:\"install_url\";s:45:\"https://meowapps.com/products/mwai-websearch/\";s:12:\"settings_url\";N;s:5:\"stars\";i:5;s:7:\"enabled\";b:0;}i:4;a:7:{s:4:\"slug\";s:17:\"mwai-better-links\";s:4:\"name\";s:12:\"Better Links\";s:11:\"description\";s:120:\"Validate internal and external links and map specific terms to custom URLs, ensuring smoother navigation and references.\";s:11:\"install_url\";s:48:\"https://meowapps.com/products/mwai-better-links/\";s:12:\"settings_url\";N;s:5:\"stars\";i:3;s:7:\"enabled\";b:0;}i:5;a:7:{s:4:\"slug\";s:15:\"mwai-woo-basics\";s:4:\"name\";s:10:\"Woo Basics\";s:11:\"description\";s:125:\"Access essential WooCommerce data so your chatbot can understand products, orders, and more for a richer shopping experience.\";s:11:\"install_url\";s:46:\"https://meowapps.com/products/mwai-woo-basics/\";s:12:\"settings_url\";N;s:5:\"stars\";i:2;s:7:\"enabled\";b:0;}i:6;a:7:{s:4:\"slug\";s:18:\"mwai-quick-actions\";s:4:\"name\";s:13:\"Quick Actions\";s:11:\"description\";s:102:\"Enable dynamic quick actions at chat start or during events, helping users find what they need faster.\";s:11:\"install_url\";s:49:\"https://meowapps.com/products/mwai-quick-actions/\";s:12:\"settings_url\";N;s:5:\"stars\";i:3;s:7:\"enabled\";b:0;}i:7;a:7:{s:4:\"slug\";s:19:\"mwai-content-parser\";s:4:\"name\";s:14:\"Content Parser\";s:11:\"description\";s:123:\"Parse complex website content, including ACF fields and page builders, for more precise embeddings and knowledge retrieval.\";s:11:\"install_url\";s:50:\"https://meowapps.com/products/mwai-content-parser/\";s:12:\"settings_url\";N;s:5:\"stars\";i:2;s:7:\"enabled\";b:0;}i:8;a:7:{s:4:\"slug\";s:17:\"mwai-visitor-form\";s:4:\"name\";s:12:\"Visitor Form\";s:11:\"description\";s:115:\"Add a customizable form triggered by specific events in your chatbot to collect key visitor information seamlessly.\";s:11:\"install_url\";s:48:\"https://meowapps.com/products/mwai-visitor-form/\";s:12:\"settings_url\";N;s:5:\"stars\";i:2;s:7:\"enabled\";b:0;}i:9;a:7:{s:4:\"slug\";s:17:\"mwai-dynamic-keys\";s:4:\"name\";s:12:\"Dynamic Keys\";s:11:\"description\";s:106:\"Rotate multiple API keys dynamically for any environment, balancing usage and ensuring smooth performance.\";s:11:\"install_url\";s:48:\"https://meowapps.com/products/mwai-dynamic-keys/\";s:12:\"settings_url\";N;s:5:\"stars\";i:1;s:7:\"enabled\";b:0;}i:10;a:7:{s:4:\"slug\";s:16:\"mwai-user-memory\";s:4:\"name\";s:11:\"User Memory\";s:11:\"description\";s:122:\"Let your chatbot remember details about logged-in users across conversations, for more personal and context-aware replies.\";s:11:\"install_url\";s:47:\"https://meowapps.com/products/mwai-user-memory/\";s:12:\"s