(274,1,'2026-09-01 23:42:00','2026-09-01 21:42:00','<!-- wp:group {\"className\":\"section container grid grid\\u002d\\u002d2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section container grid grid--2\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Nos coordonnées</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"mt-md\"} -->\n<ul class=\"wp-block-list mt-md\"><!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>Adresse</strong><br>Adresse placeholder, Antananarivo, Madagascar</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong><strong>Téléphone</strong></strong><br>+261 XX XX XXX XX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>E-mail</strong><br><a href=\"mailto:contact@ankizy-generation.org\">contact@ankizy-generation.org</a><br></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>Horaires</strong><br>Lundi – Vendredi, 8h – 17h (placeholder)<br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"placeholder placeholder\\u002d\\u002dwide mt-md\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group placeholder placeholder--wide mt-md\"><!-- wp:group {\"className\":\"placeholder__label\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group placeholder__label\"><!-- wp:paragraph {\"className\":\"placeholder__icon\"} -->\n<p class=\"placeholder__icon\">📍</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph -->\n<p>Carte / localisation placeholder</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"partenariat form-tabs\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group partenariat form-tabs\"><!-- wp:html -->\n<style data-wp-block-html=\"css\">\n/* =========================================\n   CONTACT — ONGLETS\n   ========================================= */\n\n.ankizy-contact-tabs {\n    width: 100%;\n    max-width: 100%;\n}\n\n/* Les deux onglets */\n.ankizy-contact-tab-buttons {\n    display: flex;\n    width: 100%;\n    margin-bottom: 30px;\n    border-bottom: 1px solid #d5e4dc;\n}\n\n/* Bouton d\'onglet */\n.ankizy-contact-tab {\n    flex: 1;\n    width: 50%;\n    padding: 14px 20px;\n    border: none;\n    background: transparent;\n    color: #555;\n    font-family: inherit;\n    font-size: 16px;\n    font-weight: 600;\n    text-align: center;\n    cursor: pointer;\n    border-bottom: 3px solid transparent;\n}\n\n/* Onglet actif */\n.ankizy-contact-tab.active {\n    color: #23833a;\n    border-bottom-color: #23833a;\n}\n\n/* Hover */\n.ankizy-contact-tab:hover {\n    color: #23833a;\n}\n\n/* Formulaires */\n.ankizy-contact-panel {\n    display: none;\n}\n\n.ankizy-contact-panel.active {\n    display: block;\n}\n\n\n/* =========================================\n   CONTACT FORM 7\n   ========================================= */\n\n.ankizy-contact-panel .wpcf7-form {\n    width: 100%;\n}\n\n.ankizy-contact-panel .wpcf7-form p {\n    margin: 0 0 18px;\n}\n\n\n/* Labels */\n.ankizy-contact-panel .wpcf7-form label {\n    display: block;\n    margin-bottom: 7px;\n    color: #222;\n    font-size: 15px;\n    font-weight: 600;\n}\n\n\n/* Champs */\n.ankizy-contact-panel .wpcf7-form-control:not(.wpcf7-submit) {\n    box-sizing: border-box;\n    width: 100%;\n    max-width: 100%;\n    padding: 12px 14px;\n    border: 1px solid #aeb8b3;\n    border-radius: 4px;\n    background: #fff;\n    font-family: inherit;\n    font-size: 15px;\n}\n\n\n/* Textarea */\n.ankizy-contact-panel textarea.wpcf7-form-control {\n    min-height: 150px;\n    height: 150px;\n    resize: vertical;\n}\n\n\n/* Focus */\n.ankizy-contact-panel .wpcf7-form-control:focus {\n    outline: none;\n    border-color: #23833a;\n    box-shadow: 0 0 0 2px rgba(35, 131, 58, 0.10);\n}\n\n\n/* Bouton envoyer */\n.ankizy-contact-panel input.wpcf7-submit {\n    display: block;\n    width: 100%;\n    padding: 13px 20px;\n    border: none;\n    border-radius: 5px;\n    background: #23833a;\n    color: #fff;\n    font-family: inherit;\n    font-size: 15px;\n    font-weight: 700;\n    cursor: pointer;\n    transition: 0.2s ease;\n}\n\n.ankizy-contact-panel input.wpcf7-submit:hover {\n    background: #1b6d30;\n}\n\n\n/* Messages CF7 */\n.ankizy-contact-panel .wpcf7-response-output {\n    margin: 20px 0 0;\n}\n\n\n/* =========================================\n   PARTENARIAT : NOM + ORGANISATION\n   ========================================= */\n\n.ankizy-partnership-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 20px;\n}\n\n\n/* =========================================\n   MOBILE\n   ========================================= */\n\n@media (max-width: 700px) {\n\n    .ankizy-contact-tab-buttons {\n        flex-direction: column;\n    }\n\n    .ankizy-contact-tab {\n        width: 100%;\n    }\n\n    .ankizy-partnership-row {\n        grid-template-columns: 1fr;\n    }\n}\n</style>\n\n<div class=\"ankizy-contact-tabs\">\n\n    <div class=\"ankizy-contact-tab-buttons\">\n        <button type=\"button\" class=\"ankizy-contact-tab active\" data-tab=\"contact-general\">\n            Contact général\n        </button>\n\n        <button type=\"button\" class=\"ankizy-contact-tab\" data-tab=\"partenariat\">\n            Demande de partenariat\n        </button>\n    </div>\n\n    <div id=\"contact-general\" class=\"ankizy-contact-panel active\">\n    </div>\n\n    <div id=\"partenariat\" class=\"ankizy-contact-panel\">\n\n    </div>\n\n</div>\n<!-- /wp:html --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','25-revision-v1','','','2026-09-01 23:42:00','2026-09-01 21:42:00','',25,'http://localhost:8080/?p=274',0,'revision','',0),
