{\n\n            const target = this.dataset.tab;\n\n            /* Tous les boutons deviennent inactifs */\n            tabs.forEach(function (item) {\n                item.classList.remove(\"active\");\n            });\n\n            /* Le bouton cliqué devient actif */\n            this.classList.add(\"active\");\n\n\n            /* Cacher les deux formulaires */\n            const general = document.querySelector(\n                \".ankizy-contact-panel-general\"\n            );\n\n            const partenariat = document.querySelector(\n                \".ankizy-contact-panel-partenariat\"\n            );\n\n\n            if (general) {\n                general.style.display = \"none\";\n            }\n\n            if (partenariat) {\n                partenariat.style.display = \"none\";\n            }\n\n\n            /* Afficher le formulaire choisi */\n            if (target === \"contact-general\" && general) {\n\n                general.style.display = \"block\";\n\n            }\n\n            if (target === \"partenariat\" && partenariat) {\n\n                partenariat.style.display = \"block\";\n\n            }\n\n        });\n\n    });\n\n});\n</script>\n\n<div class=\"ankizy-contact-tabs\">\n\n    <div class=\"ankizy-contact-tab-buttons\">\n\n        <button type=\"button\" class=\"ankizy-contact-tab active\" data-tab=\"contact-general\">\n            Contact général\n        </button>\n\n        <button type=\"button\" class=\"ankizy-contact-tab\" data-tab=\"partenariat\">\n            Demande de partenariat\n        </button>\n\n    </div>\n\n</div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"ankizy-contact-panel ankizy-contact-panel-general\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group ankizy-contact-panel ankizy-contact-panel-general\"><!-- wp:contact-form-7/contact-form-selector {\"id\":243,\"hash\":\"f4e68b4\",\"title\":\"Contact général\"} -->\n<div class=\"wp-block-contact-form-7-contact-form-selector\">[contact-form-7 id=\"f4e68b4\" title=\"Contact général\"]</div>\n<!-- /wp:contact-form-7/contact-form-selector --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"ankizy-contact-panel ankizy-contact-panel-partenariat\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group ankizy-contact-panel ankizy-contact-panel-partenariat\"><!-- wp:contact-form-7/contact-form-selector {\"id\":244,\"hash\":\"1e4f05a\",\"title\":\"Demande de partenariat\"} -->\n<div class=\"wp-block-contact-form-7-contact-form-selector\">[contact-form-7 id=\"1e4f05a\" title=\"Demande de partenariat\"]</div>\n<!-- /wp:contact-form-7/contact-form-selector --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','25-revision-v1','','','2026-09-02 00:10:46','2026-09-01 22:10:46','',25,'http://localhost:8080/?p=292',0,'revision','',0),
(293,1,'2026-09-02 00:12:59','2026-09-01 22:12:59','<!-- wp:group {\"className\":\"section container grid grid\\u002d\\u002d2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section container grid grid--2\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Nos coordonnées</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"mt-md\"} -->\n<ul class=\"wp-block-list mt-md\"><!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>Adresse</strong><br>Adresse placeholder, Antananarivo, Madagascar</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong><strong>Téléphone</strong></strong><br>+261 XX XX XXX XX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>E-mail</strong><br><a href=\"mailto:contact@ankizy-generation.org\">contact@ankizy-generation.org</a><br></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"className\":\"mt-sm\"} -->\n<li class=\"mt-sm\"><strong>Horaires</strong><br>Lundi – Vendredi, 8h – 17h (placeholder)<br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"placeholder placeholder\\u002d\\u002dwide mt-md\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group placeholder placeholder--wide mt-md\"><!-- wp:group {\"className\":\"placeholder__label\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group placeholder__label\"><!-- wp:paragraph {\"className\":\"placeholder__icon\"} -->\n<p class=\"placeholder__icon\">📍</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph -->\n<p>Carte / localisation placeholder</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"partenariat form-tabs\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group partenariat form-tabs\"><!-- wp:html -->\n<style data-wp-block-html=\"css\">\n/* ==========================================================\n   CONTACT FORM 7 — ADAPTATION DU DESIGN ANKIZY GÉNÉRATION\n   ========================================================== */\n\n\n/* Conteneur CF7 */\n.ankizy-contact-panel .wpcf7 {\n    width: 100%;\n    max-width: 640px;\n}\n\n\n/* Formulaire CF7 */\n.ankizy-contact-panel .wpcf7 form {\n    width: 100%;\n}\n\n\n/* CF7 génère des <p> automatiquement */\n.ankizy-contact-panel .wpcf7 form > p {\n    margin: 0;\n    padding: 0;\n}\n\n\n/* Groupes */\n.ankizy-contact-panel .form__group {\n    margin-bottom: var(--space-md);\n}\n\n\n/* Labels */\n.ankizy-contact-panel .form__label {\n    display: block;\n    font-weight: 700;\n    font-size: 0.9rem;\n    margin-bottom: var(--space-3xs);\n}\n\n\n/* Astérisque */\n.ankizy-contact-panel .required {\n    color: var(--color-alert);\n}\n\n\n/* ==========================================================\n   CHAMPS\n   ========================================================== */\n\n.ankizy-contact-panel .form__input,\n.ankizy-contact-panel .form__textarea,\n.ankizy-contact-panel .form__select {\n\n    display: block;\n    box-sizing: border-box;\n\n    width: 100%;\n    max-width: 100%;\n\n    padding: 0.75em 0.9em;\n\n    border: 1px solid var(--color-border);\n    border-radius: var(--radius-sm);\n\n    background: #fff;\n    color: var(--color-text);\n\n    font-family: inherit;\n    font-size: inherit;\n\n    transition:\n        border-color 0.15s ease,\n        box-shadow 0.15s ease;\n}\n\n\n/* Focus */\n.ankizy-contact-panel .form__input:focus,\n.ankizy-contact-panel .form__textarea:focus,\n.ankizy-contact-panel .form__select:focus {\n\n    border-color: var(--color-action);\n\n    box-shadow:\n        0 0 0 3px var(--color-action-bg);\n\n    outline: none;\n}\n\n\n/* ==========================================================\n   TEXTAREA\n   ========================================================== */\n\n.ankizy-contact-panel .form__textarea {\n\n    min-height: 120px;\n\n    resize: vertical;\n}\n\n\n/* ==========================================================\n   LIGNE NOM + ORGANISATION\n   ========================================================== */\n\n.ankizy-contact-panel .form__row {\n\n    display: grid;\n\n    grid-template-columns: 1fr 1fr;\n\n    gap: var(--space-md);\n}\n\n\n/* ==========================================================\n   BOUTON\n   ========================================================== */\n\n.ankizy-contact-panel .wpcf7-submit {\n\n    display: block;\n\n    width: 100%;\n\n    padding: 0.75em 1.2em;\n\n    border: none;\n    border-radius: var(--radius-sm);\n\n    background: var(--color-action);\n    color: #fff;\n\n    font-family: inherit;\n    font-size: inherit;\n    font-weight: 700;\n\n    cursor: pointer;\n\n    transition:\n        background-color 0.15s ease,\n        transform 0.15s ease;\n}\n\n\n.ankizy-contact-panel .wpcf7-submit:hover {\n\n    background: var(--color-action-dark);\n\n}\n\n\n.ankizy-contact-panel .wpcf7-submit:focus {\n\n    outline: none;\n\n    box-shadow:\n        0 0 0 3px var(--color-action-bg);\n}\n\n\n/* ==========================================================\n   MESSAGES D\'ERREUR CF7\n   ========================================================== */\n\n.ankizy-contact-panel .wpcf7-not-valid {\n\n    border-color: var(--color-alert) !important;\n}\n\n\n.ankizy-contact-panel .wpcf7-not-valid-tip {\n\n    color: var(--color-alert);\n\n    font-size: 0.78rem;\n\n    margin-top: 4px;\n}\n\n\n/* ==========================================================\n   MESSAGE APRÈS ENVOI\n   ========================================================== */\n\n.ankizy-contact-panel .wpcf7-response-output {\n\n    margin: var(--space-md) 0 0;\n\n    padding: var(--space-sm);\n\n    border-radius: var(--radius-sm);\n\n    font-size: 0.88rem;\n}\n\n\n/* ==========================================================\n   ONGLETS\n   ========================================================== */\n\n.ankizy-contact-tabs {\n\n    width: 100%;\n\n    margin-bottom: var(--space-md);\n}\n\n\n.ankizy-contact-tab-buttons {\n\n    display: flex;\n\n    gap: var(--space-2xs);\n\n    margin-bottom: var(--space-md);\n\n    border-bottom: 1px solid var(--color-border);\n}\n\n\n.ankizy-contact-tab {\n\n    flex: 1;\n\n    background: none;\n\n    border: none;\n\n    cursor: pointer;\n\n    padding: var(--space-xs) var(--space-sm);\n\n    font-family: inherit;\n\n    font-size: 0.9rem;\n\n    font-weight: 700;\n\n    color: var(--color-text-muted);\n\n    border-bottom: 2px solid transparent;\n\n    margin-bottom: -1px;\n\n    transition:\n        color 0.15s ease,\n        border-color 0.15s ease;\n}\n\n\n.ankizy-contact-tab.active {\n\n    color: var(--color-action);\n\n    border-bottom-color: var(--color-action);\n}\n\n\n.ankizy-contact-tab:hover {\n\n    color: var(--color-action);\n\n}\n\n\n/* ==========================================================\n   RESPONSIVE\n   ========================================================== */\n\n@media (max-width: 700px) {\n\n    .ankizy-contact-tab-buttons {\n\n        gap: 0;\n\n    }\n\n    .ankizy-contact-tab {\n\n        padding-inline: 8px;\n\n        font-size: 0.82rem;\n\n    }\n\n    .ankizy-contact-panel .form__row {\n\n        grid-template-columns: 1fr;\n\n    }\n\n}\n.ankizy-contact-panel {\n    display: none;\n}\n\n.ankizy-contact-panel-general {\n    display: block;\n}\n</style>\n\n<script data-wp-block-html=\"js\">\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n\n    const tabs = document.querySelectorAll(\".ankizy-contact-tab\");\n\n    if (!tabs.length) {\n        return;\n    }\n\n    tabs.forEach(function (tab) {\n\n        tab.addEventListener(\"click\", function () {\n\n            const target = this.dataset.tab;\n\n            /* Tous les boutons deviennent inactifs */\n            tabs.forEach(function (item) {\n                item.classList.remove(\"active\");\n            });\n\n            /* Le bouton cliqué devient actif */\n            this.classList.add(\"active\");\n\n\n            /* Cacher les deux formulaires */\n            const general = document.querySelector(\n                \".ankizy-contact-panel-general\"\n            );\n\n            const partenariat = document.querySelector(\n                \".ankizy-contact-panel-partenariat\"\n            );\n\n\n            if (general) {\n                general.style.display = \"none\";\n            }\n\n            if (partenariat) {\n                partenariat.style.display = \"none\";\n            }\n\n\n            /* Afficher le formulaire choisi */\n            if (target === \"contact-general\" && general) {\n\n                general.style.display = \"block\";\n\n            }\n\n            if (target === \"partenariat\" && partenariat) {\n\n                partenariat.style.display = \"block\";\n\n            }\n\n        });\n\n    });\n\n});\n</script>\n\n<div class=\"ankizy-contact-tabs\">\n\n    <div class=\"ankizy-contact-tab-buttons\">\n\n        <button type=\"button\" class=\"ankizy-contact-tab active\" data-tab=\"contact-general\">\n            Contact général\n        </button>\n\n        <button type=\"button\" class=\"ankizy-contact-tab\" data-tab=\"partenariat\">\n            Demande de partenariat\n        </button>\n\n    </div>\n\n</div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"ankizy-contact-panel ankizy-contact-panel-general active\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group ankizy-contact-panel ankizy-contact-panel-general active\"><!-- wp:contact-form-7/contact-form-selector {\"id\":243,\"hash\":\"f4e68b4\",\"title\":\"Contact général\"} -->\n<div class=\"wp-block-contact-form-7-contact-form-selector\">[contact-form-7 id=\"f4e68b4\" title=\"Contact général\"]</div>\n<!-- /wp:contact-form-7/contact-form-selector --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"ankizy-contact-panel ankizy-contact-panel-partenariat\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group ankizy-contact-panel ankizy-contact-panel-partenariat\"><!-- wp:contact-form-7/contact-form-selector {\"id\":244,\"hash\":\"1e4f05a\",\"title\":\"Demande de partenariat\"} -->\n<div class=\"wp-block-contact-form-7-contact-form-selector\">[contact-form-7 id=\"1e4f05a\" title=\"Demande de partenariat\"]</div>\n<!-- /wp:contact-form-7/contact-form-selector --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','25-revision-v1','','','2026-09-02 00:12:59','2026-09-01 22:12:59','',25,'http://localhost:8080/?p=293',0,'revision','',0),
